<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetContentVO;

trait TemplateAssetContentAccessor
{
    private TemplateAssetContentVO $_content;
    public function getContent(): string
    {
        return $this->_content->value();
    }
    public function content(): TemplateAssetContentVO
    {
        return $this->_content;
    }
    public function isContentChanged(?self $original = null): bool
    {
        return !$this->_content->equals($original?->_content);
    }
    public function withContent(TemplateAssetContentVO|string $content): self
    {
        $copy = clone $this;
        $copy->_content = TemplateAssetContentVO::from($content);
        return $copy;
    }
}
